template <int N>
struct Factorial {
    enum { value = N * Factorial<N - 1>::value };
};

template <>
struct Factorial<0> { // Base case specialization
    enum { value = 1 };
};

// C++03/11 Compile-time computation using struct definition
int result = Factorial<6>::value; // result = 720

// C++11/14 alternative via constexpr function recursion
constexpr int Fib(int n) {
    return (n <= 1) ? n : Fib(n-1) + Fib(n-2);
}

constexpr int fib_val = Fib(8); // Evaluated at compile time
